#include <functional>

int subtract(int a, int b) { return a - b; }

// std::placeholders::_1 represents the first argument passed to the bound object
auto subtract_from_ten = std::bind(subtract, 10, std::placeholders::_1);

// Example usage:
// int result = subtract_from_ten(3); // result will be 7
```

```cpp
#include <functional>
#include <iostream>

class Foo {
public:
    void print(int x) { std::cout << "Foo::print(" << x << ")" << std::endl; }
};

// ... inside main or another function ...
Foo foo_obj;
auto printer = std::bind(&Foo::print, &foo_obj, std::placeholders::_1);

// Example usage:
// printer(42); // Calls foo_obj.print(42)
